// 1) Webhook에서 받은 입력(필터/PR 링크 등)
const webhookBody = $('Webhook').first().json.body;

// 2) pr_req(현재 Code 노드로 들어오는 items)에서 patch 있는 파일만 모아서 diff 합치기
const filesWithPatch = items.filter((item) => item.json.patch);

const combinedDiff = filesWithPatch
  .map((item) => {
    return `### File: ${item.json.filename} (Status: ${item.json.status})\nDiff:\n${item.json.patch.slice(0, 1500)}`;
  })
  .join('\n\n---\n\n');

// 3) 다른 노드 응답(댓글/라인댓글) 가져오기
const normalizeList = (nodeName) => {
  const arr = $(nodeName).all().map((i) => i.json);
  // HTTP Request가 "한 item 안에 배열"로 들어오는 경우 대응
  if (arr.length === 1 && Array.isArray(arr[0])) return arr[0];
  return arr;
};

const issueComments = normalizeList('comment req');       // /issues/{n}/comments
const lineReviewComments = normalizeList('line review req'); // /pulls/{n}/comments

// 4) 토큰 아끼려고 body 정리(코드래빗 같은 긴 주석 제거용)
const cleanText = (s = '') =>
  String(s)
    .replace(/<!--[\s\S]*?-->/g, '') // HTML 주석 제거
    .replace(/<[^>]*>/g, '')         // HTML 태그 제거
    .replace(/\n{3,}/g, '\n\n')
    .trim();

// 5) 문자열로 합치기
const issueText =
  issueComments.length === 0
    ? '없음'
    : issueComments
        .map((c, idx) => {
          const author = c.user?.login ?? 'unknown';
          const at = c.created_at ?? '';
          const body = cleanText(c.body).slice(0, 1200);
          return `[#${idx + 1}] ${author} ${at}\n${body}`;
        })
        .join('\n\n---\n\n');

const lineText =
  lineReviewComments.length === 0
    ? '없음'
    : lineReviewComments
        .map((c, idx) => {
          const author = c.user?.login ?? 'unknown';
          const at = c.created_at ?? '';
          const pos = c.path
            ? `${c.path}${c.line ? `:${c.line}` : ''}`
            : '';
          const body = cleanText(c.body).slice(0, 600);
          return `[#${idx + 1}] ${author} ${at}\n${pos}\n${body}`;
        })
        .join('\n\n---\n\n');

const fileChangeComment = `## PR 일반 댓글(Conversation)\n${issueText}\n\n## PR 라인 댓글(Files changed)\n${lineText}`;

// 6) 최종 리턴(LLM 노드에서 $json.allFilesDiff / $json.fileChangeComment로 사용)
return [
  {
    json: {
      allFilesDiff: combinedDiff,
      totalFiles: filesWithPatch.length,

      // 원본 입력을 그대로 넘김(필터/PR 링크 등)
      conversation: webhookBody,

      // 댓글/리뷰
      fileChangeComment,
    },
  },
];
